import app from 'flarum/forum/app';
export const EXT = 'ernestdefoe-homecoming';
export const t = (key, params = {}) => app.translator.trans(`${EXT}.forum.${key}`, params);
export const tText = (key, params = {}) => String(app.translator.trans(`${EXT}.forum.${key}`, params, true));

/** By the member's own clock. */
export function greeting() {
  const h = new Date().getHours();
  return tText(`greeting.${h >= 5 && h < 12 ? 'morning' : h >= 12 && h < 17 ? 'afternoon' : 'evening'}`);
}
export function firstName(user) {
  return String(user.displayName() || user.username() || '').split(/\s+/)[0];
}
const format = n => new Intl.NumberFormat(app.translator.getLocale?.() || undefined).format(n);
export const count = (n, cap = 100) => n >= cap ? `${cap - 1}+` : format(n);

/** Renown's rank name: the admin's, else the language pack's. */
function renownRankName(rank) {
  const custom = app.forum.attribute('renown')?.ranks?.[rank - 1]?.name;
  return custom || String(app.translator.trans(`ernestdefoe-renown.lib.ranks.${rank}`, {}, true));
}

/** The member's most visible group: the first one that isn't "Member" or hidden. */
function topGroup(user) {
  const groups = user.groups() || [];
  return groups.find(g => g && g.id() !== '3' && !g.isHidden?.()) || null;
}
/** A rank from the points extension, else the top group, else nothing. */
export function pill(user, progress) {
  if (progress?.source === 'renown' && progress.rank) return {
    name: renownRankName(progress.rank),
    color: null,
    icon: 'fas fa-star'
  };
  if (progress?.name) return {
    name: progress.name,
    color: progress.color || null,
    icon: 'fas fa-star'
  };
  const group = topGroup(user);
  return group ? {
    name: group.nameSingular(),
    color: group.color() || null,
    icon: group.icon() || null
  } : null;
}
export function climb(p) {
  if (!p) return null;
  const next = p.source === 'renown' ? p.nextRank ? renownRankName(p.nextRank) : null : p.nextName || null;
  if (p.max === null || p.max === undefined || !next) return {
    pct: 100,
    remaining: 0,
    next: null
  };
  const span = Math.max(1, p.max - p.min);
  return {
    pct: Math.max(0, Math.min(100, Math.round((p.points - p.min) / span * 100))),
    remaining: Math.max(0, p.max - p.points),
    next
  };
}
export function statLabel(stat) {
  return t(`stats.${stat.key}`);
}
export function statValue(stat) {
  if (stat.value === null || stat.value === undefined) return '–';
  if (stat.key === 'joined') return dayjs(String(stat.value)).format('MMM YYYY');
  return format(Number(stat.value));
}

/** WMO weather codes, as Open-Meteo sends them. */
export function condition(code) {
  if (code === 0) return 'clear';
  if (code === 1) return 'mostly_clear';
  if (code === 2) return 'partly_cloudy';
  if (code === 3) return 'cloudy';
  if (code === 45 || code === 48) return 'fog';
  if (code >= 51 && code <= 57) return 'drizzle';
  if (code === 66 || code === 67) return 'freezing_rain';
  if (code >= 61 && code <= 65) return 'rain';
  if (code >= 71 && code <= 77) return 'snow';
  if (code >= 80 && code <= 82) return 'showers';
  if (code === 85 || code === 86) return 'snow_showers';
  if (code >= 95) return 'thunderstorm';
  return 'cloudy';
}
export function weatherIcon(code, day) {
  const c = condition(code);
  if (c === 'clear' || c === 'mostly_clear') return day ? 'fas fa-sun' : 'fas fa-moon';
  if (c === 'partly_cloudy') return day ? 'fas fa-cloud-sun' : 'fas fa-cloud-moon';
  if (c === 'fog') return 'fas fa-smog';
  if (c === 'drizzle' || c === 'rain' || c === 'freezing_rain') return 'fas fa-cloud-rain';
  if (c === 'showers') return 'fas fa-cloud-showers-heavy';
  if (c === 'snow' || c === 'snow_showers') return 'fas fa-snowflake';
  if (c === 'thunderstorm') return 'fas fa-cloud-bolt';
  return 'fas fa-cloud';
}
export function unit() {
  const own = app.session.user?.preferences()?.homecomingUnit;
  if (own === 'c' || own === 'f') return own;
  return app.forum.attribute('homecomingUnit') === 'f' ? 'f' : 'c';
}

/** °C in, the member's unit out. */
export function degrees(c, withUnit = true) {
  if (c === null || c === undefined) return '';
  const u = unit();
  const n = Math.round(u === 'f' ? c * 9 / 5 + 32 : c);
  return withUnit ? `${n}°${u === 'f' ? 'F' : 'C'}` : `${n}°`;
}
export const links = {
  unread: () => app.route('index', {
    q: 'is:unread'
  }),
  notifications: () => app.route('notifications'),
  newPosts: () => app.route('index', {
    sort: 'latest'
  })
};
export const canStart = () => !!app.forum.attribute('canStartDiscussion');
export function startDiscussion() {
  if (!app.session.user) return;
  app.composer.load(() => flarum.reg.asyncModuleImport('flarum/forum/components/DiscussionComposer'), {
    user: app.session.user
  }).then(() => app.composer.show());
}
export function showModal(name) {
  app.modal.show(() => flarum.reg.asyncModuleImport(`flarum/forum/components/${name}`));
}

/** "Use my location" is offered: weather and the admin switch on, a browser that can ask, over https. */
export function canLocate() {
  return !!app.forum.attribute('homecomingWeather') && !!app.forum.attribute('homecomingGeolocate') && typeof navigator !== 'undefined' && 'geolocation' in navigator && window.isSecureContext;
}
export const locating = {
  busy: false
};

/**
 * Ask the browser where the member is, only because they clicked. The point is
 * rounded to two decimals (about a kilometre) before it leaves the browser.
 * Declined, unavailable or slow: nothing changes and nothing is shown.
 */
export function useMyLocation(done) {
  if (locating.busy || !canLocate()) return;
  locating.busy = true;
  m.redraw();
  const finish = () => {
    locating.busy = false;
    m.redraw();
  };
  navigator.geolocation.getCurrentPosition(pos => {
    const round = n => Math.round(n * 100) / 100;
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/homecoming/locate',
      body: {
        lat: round(pos.coords.latitude),
        lng: round(pos.coords.longitude)
      },
      errorHandler: () => {}
    }).then(done).catch(() => {}).finally(finish);
  }, finish, {
    enableHighAccuracy: false,
    timeout: 10000,
    maximumAge: 3600000
  });
}
flarum.reg.add('ernestdefoe-homecoming', 'forum/components/util', { EXT: EXT,t: t,tText: tText,greeting: greeting,firstName: firstName,count: count,pill: pill,climb: climb,statLabel: statLabel,statValue: statValue,condition: condition,weatherIcon: weatherIcon,unit: unit,degrees: degrees,links: links,canStart: canStart,startDiscussion: startDiscussion,showModal: showModal,canLocate: canLocate,locating: locating,useMyLocation: useMyLocation, });