import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Avatar from 'flarum/common/components/Avatar';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import { dashboard } from '../store';
import { Counts, LocateButton, PillBadge, WeatherLine } from './Bits';
import { canStart, firstName, greeting, links, pill, startDiscussion, t } from './util';

/** Greeting, name, rank, unread and notifications, and the two buttons, in one row that wraps on narrow screens. */
export default class WelcomeStrip extends Component {
  view() {
    const user = app.session.user;
    const d = dashboard();
    const h = new Date().getHours();
    const level = d?.progress?.source === 'renown' ? d.progress.level : null;
    return m("section", {
      className: `Homecoming Homecoming-strip Homecoming--${this.attrs.host}`,
      "aria-label": String(t('welcome_back', {
        name: firstName(user)
      }))
    }, m("div", {
      className: "Homecoming-hello"
    }, m(Avatar, {
      user: user,
      className: "Homecoming-avatar"
    }), m("div", {
      className: "Homecoming-helloText"
    }, m("div", {
      className: "Homecoming-greeting"
    }, m(Icon, {
      name: h >= 6 && h < 19 ? 'fas fa-sun' : 'fas fa-moon',
      className: "Homecoming-greetingIcon"
    }), m("span", null, greeting()), d?.weather && d.place ? WeatherLine(d, LocateButton(d)) : LocateButton(d)), m("h2", {
      className: "Homecoming-title"
    }, t('welcome_back', {
      name: firstName(user)
    })), m("div", {
      className: "Homecoming-meta"
    }, PillBadge(pill(user, d?.progress ?? null)), level ? m("span", {
      className: "Homecoming-muted"
    }, t('level', {
      level
    })) : null))), Counts(d, 'tiles'), m("div", {
      className: "Homecoming-actions"
    }, canStart() ? m("button", {
      type: "button",
      className: "Button Button--primary",
      onclick: startDiscussion
    }, m(Icon, {
      name: "fas fa-pen",
      className: "Button-icon"
    }), m("span", {
      className: "Button-label"
    }, t('start_discussion'))) : null, m(Link, {
      className: "Button",
      href: links.newPosts()
    }, t('new_posts'))));
  }
}
flarum.reg.add('ernestdefoe-homecoming', 'forum/components/WelcomeStrip', WelcomeStrip);