import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import { dashboard } from '../store';
import { ClimbBar, PillBadge } from './Bits';
import { count, pill, statLabel, statValue, t } from './util';

/** Rank, points and the bar to the next rank (with a points extension), then four stats. */
export default class StatsCard extends Component {
  view() {
    const user = app.session.user;
    const d = dashboard();
    const p = d?.progress ?? null;
    return m("section", {
      className: `Homecoming Homecoming-card Homecoming-stats Homecoming--${this.attrs.host}`,
      "aria-label": String(t('your_stats'))
    }, m("h3", {
      className: "Homecoming-heading"
    }, t('your_stats')), p ? m("div", {
      className: "Homecoming-rank"
    }, m("div", {
      className: "Homecoming-rankRow"
    }, PillBadge(pill(user, p)), p.source === 'renown' && p.level ? m("span", {
      className: "Homecoming-muted"
    }, t('level', {
      level: p.level
    })) : null, m("span", {
      className: "Homecoming-points"
    }, t('points', {
      count: count(p.points, Infinity)
    }))), ClimbBar(d)) : null, m("dl", {
      className: "Homecoming-grid"
    }, (d?.stats || []).map(s => m("div", {
      className: "Homecoming-stat",
      key: s.key
    }, m("dt", null, statLabel(s)), m("dd", null, statValue(s))))));
  }
}
flarum.reg.add('ernestdefoe-homecoming', 'forum/components/StatsCard', StatsCard);