import app from 'flarum/forum/app';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import { refresh } from '../store';
import { canLocate, climb, count, degrees, links, locating, t, tText, useMyLocation, weatherIcon, condition } from './util';

/** The rank or group pill, in the group's colour when it has one. */
export function PillBadge(p, small = false) {
  if (!p) return null;
  return m("span", {
    className: `Homecoming-pill${small ? ' Homecoming-pill--small' : ''}`,
    style: p.color ? {
      '--homecoming-pill': p.color,
      '--homecoming-pill-text': textOn(p.color)
    } : undefined
  }, p.icon ? m(Icon, {
    name: p.icon
  }) : null, m("span", null, p.name));
}

/** Dark or light text, whichever reads on an admin-chosen group colour (light groups exist). */
function textOn(color) {
  const hex = color.replace('#', '');
  const full = hex.length === 3 ? hex.replace(/./g, c => c + c) : hex;
  if (!/^[0-9a-f]{6}$/i.test(full)) return '#fff';
  const [r, g, b] = [0, 2, 4].map(i => parseInt(full.slice(i, i + 2), 16));
  return (r * 299 + g * 587 + b * 114) / 1000 >= 150 ? '#111' : '#fff';
}

/** "64°F, partly cloudy in Portland", or nothing. */
/** The weather, with anything passed in kept on the same line (the location button never wraps alone). */
export function WeatherLine(d, after = null) {
  if (!d?.weather || !d.place) return null;
  const w = d.weather;
  return m("span", {
    className: "Homecoming-weather"
  }, m(Icon, {
    name: weatherIcon(w.code, w.day)
  }), m("span", null, t('weather.line', {
    temp: degrees(w.temp),
    condition: tText(`weather.${condition(w.code)}`),
    place: shortPlace(d.place.label)
  })), after);
}
export function shortPlace(label) {
  return label.split(',')[0].trim() || tText('weather.your_location');
}

/** After a new place: ask now, and again once the background fetch has had time to bring its forecast. */
export function refreshPlace() {
  refresh();
  setTimeout(refresh, 5000);
}

/**
 * "Use my location": an icon beside the weather, or a small text button where
 * there is no weather yet. Never asks on its own.
 */
export function LocateButton(d) {
  if (!canLocate() || !d) return null;
  const label = tText('weather.use_location');
  const icon = m(Icon, {
    name: locating.busy ? 'fas fa-spinner fa-spin' : 'fas fa-location-crosshairs'
  });
  return d.weather && d.place ? m("button", {
    type: "button",
    className: "Homecoming-locate",
    "aria-label": label,
    title: label,
    disabled: locating.busy,
    onclick: () => useMyLocation(refreshPlace)
  }, icon) : m("button", {
    type: "button",
    className: "Homecoming-locate Homecoming-locate--text",
    disabled: locating.busy,
    onclick: () => useMyLocation(refreshPlace)
  }, icon, m("span", null, t('weather.for_my_location')));
}

/** Unread discussions and notifications, as links. */
export function Counts(d, variant) {
  const user = app.session.user;
  const unread = d ? d.unread : null;
  const notes = Number(user.unreadNotificationCount?.() ?? 0);
  if (variant === 'rows') {
    return m("nav", {
      className: "Homecoming-rows",
      "aria-label": tText('unread_short')
    }, m(Link, {
      className: "Homecoming-row",
      href: links.unread()
    }, m(Icon, {
      name: "far fa-comments"
    }), m("span", {
      className: "Homecoming-rowLabel"
    }, t('unread_short')), m("span", {
      className: "Homecoming-badge"
    }, unread === null ? '–' : count(unread))), m(Link, {
      className: "Homecoming-row",
      href: links.notifications()
    }, m(Icon, {
      name: "far fa-bell"
    }), m("span", {
      className: "Homecoming-rowLabel"
    }, t('notifications_short')), m("span", {
      className: "Homecoming-badge"
    }, count(notes))));
  }
  return m("nav", {
    className: "Homecoming-tiles",
    "aria-label": tText('unread_short')
  }, m(Link, {
    className: "Homecoming-tile",
    href: links.unread()
  }, m("span", {
    className: "Homecoming-tileCount"
  }, m("span", {
    className: "Homecoming-dot",
    "aria-hidden": "true"
  }), unread === null ? '–' : count(unread)), m("span", {
    className: "Homecoming-tileLabel"
  }, t('unread', {
    count: unread ?? 0
  }))), m(Link, {
    className: "Homecoming-tile",
    href: links.notifications()
  }, m("span", {
    className: "Homecoming-tileCount"
  }, m(Icon, {
    name: "far fa-bell"
  }), count(notes)), m("span", {
    className: "Homecoming-tileLabel"
  }, t('notifications', {
    count: notes
  }))));
}

/** The bar and "160 more to Veteran". Nothing without a points extension. */
export function ClimbBar(d) {
  const c = climb(d?.progress ?? null);
  if (!c) return null;
  return m("div", {
    className: "Homecoming-climb"
  }, m("div", {
    className: "Homecoming-bar",
    role: "progressbar",
    "aria-valuemin": 0,
    "aria-valuemax": 100,
    "aria-valuenow": c.pct,
    "aria-label": c.next ? tText('progress_label', {
      rank: c.next
    }) : tText('top_rank')
  }, m("div", {
    className: "Homecoming-barFill",
    style: {
      width: `${c.pct}%`
    }
  })), m("div", {
    className: "Homecoming-climbText"
  }, c.next ? t('to_next', {
    count: count(c.remaining, Infinity),
    rank: m("strong", null, c.next)
  }) : t('top_rank')));
}
flarum.reg.add('ernestdefoe-homecoming', 'forum/components/Bits', { PillBadge: PillBadge,WeatherLine: WeatherLine,shortPlace: shortPlace,refreshPlace: refreshPlace,LocateButton: LocateButton,Counts: Counts,ClimbBar: ClimbBar, });